--- a/serve/continuous_batcher/scheduler.cc
+++ b/serve/continuous_batcher/scheduler.cc
@@ -312,6 +312,22 @@
-  // previous greedy dispatch
+  // new queueing window: allow requests that arrive within window_ms to join
+  // in-progress batch to improve packing for mixed sizes
+  if (now - batch.start_time <= cfg.queue_window_ms) {
+    batch.accept_new_requests();
+  } else {
+    batch.close_for_new_requests();
+  }
--- a/serve/continuous_batcher/admission_controller.cc
+++ b/serve/continuous_batcher/admission_controller.cc
@@ -45,6 +45,34 @@
+  // cap per-priority share over rolling interval to avoid domination by one class
+  if (get_share(priority) > cfg.max_priority_share) {
+    route_to_slow_path(req);
+  }
+  // starvation detection: requeue after ttl with backoff
+  if (req.wait_time() > cfg.starvation_ttl_ms) {
+    req.mark_for_requeue();
+  }
